function formPassword(form: HTMLFormElement): string {
  return String(new FormData(form).get('password') ?? '');
}

function defaultDeviceName(): string {
  const ua = navigator.userAgent;
  const platform = /iPhone/i.test(ua) ? 'iPhone' : /iPad/i.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1) ? 'iPad'
    : /Android/i.test(ua) ? 'Android' : /Macintosh/i.test(ua) ? 'Mac' : /Windows/i.test(ua) ? 'Windows' : /Linux/i.test(ua) ? 'Linux' : '浏览器设备';
  const browser = /MicroMessenger\//.test(ua) ? '微信' : /Edg(?:e|A|iOS)?\//.test(ua) ? 'Edge' : /(?:Firefox|FxiOS)\//.test(ua) ? 'Firefox'
    : /(?:Chrome|CriOS)\//.test(ua) && !/OPR\//.test(ua) ? 'Chrome' : /Version\/.*Safari\//.test(ua) ? 'Safari' : '';
  return browser ? `${platform} · ${browser}` : platform;
}

function roomDeviceKind(name:string):'phone'|'computer'|'unknown'{return /^(iPhone|Android)\b/i.test(name)?'phone':/^(Mac|Windows|Linux)\b/i.test(name)?'computer':'unknown';}

async function deviceLinkSafetyCode(linkId: string, authorizer: RoomMember, target: RoomMember): Promise<string> {
  const material = canonicalStringify({
    v: 1,
    linkId,
    authorizer: memberBundle(authorizer),
    target: memberBundle(target),
  });
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(material)));
  const digits = (digest[0]! << 16) | (digest[1]! << 8) | digest[2]!;
  return String(digits % 1_000_000).padStart(6, '0').replace(/(\d{3})(\d{3})/, '$1 $2');
}

function timeLabel(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit' }).format(date);
}

function memberBundle(member: RoomMember) {
  return {
    deviceId: member.deviceId,
    encryptionKey: member.encryptionKey,
    signingKey: member.signingKey,
    ...(member.mlsKeyPackage ? { mlsKeyPackage: member.mlsKeyPackage } : {}),
  };
}

function setBusy(button: HTMLButtonElement, busy: boolean, busyLabel = '处理中…'): void {
  if (!button.dataset.label) button.dataset.label = button.textContent ?? '';
  button.disabled = busy;
  button.setAttribute('aria-busy', String(busy));
  const nextLabel = busy ? busyLabel : button.dataset.label;
  if (button.textContent !== nextLabel) {
    button.textContent = nextLabel;
    retargetMotion(button, button.getAnimations().find(animation => animation.effect instanceof KeyframeEffect
      && animation.effect.getKeyframes().some(frame => frame.opacity !== undefined)), { opacity: .65 }, { opacity: 1 }, motion.feedback);
  }
}

function viewerSourceTransform(source: HTMLElement | null | undefined, image: HTMLElement): string | null {
  const layer = image.closest<HTMLElement>('.viewer-media-layer');
  if (!source?.isConnected || !image.isConnected || !layer) return null;
  const origin = (source.querySelector('img') ?? source).getBoundingClientRect();
  const target = image.getBoundingClientRect();
  if (origin.width < 1 || origin.height < 1 || target.width < 1 || target.height < 1
    || origin.bottom <= 0 || origin.top >= innerHeight || origin.right <= 0 || origin.left >= innerWidth) return null;
  // The image element fills the stage, but contain paints only its intrinsic
  // aspect ratio. Include both its zoom/pan and the interrupted layer transform.
  const ratio = image instanceof HTMLImageElement && image.naturalWidth && image.naturalHeight
    ? image.naturalWidth / image.naturalHeight : target.width / target.height;
  const width = Math.min(target.width, target.height * ratio);
  const height = width / ratio;
  const relativeScale = Math.min(origin.width / width, origin.height / height);
  const current = new DOMMatrixReadOnly(getComputedStyle(layer).transform);
  const bounds = layer.getBoundingClientRect();
  const centerX = bounds.left + bounds.width / 2 - current.m41;
  const centerY = bounds.top + bounds.height / 2 - current.m42;
  const x = origin.left + origin.width / 2 - centerX
    - relativeScale * (target.left + target.width / 2 - centerX - current.m41);
  const y = origin.top + origin.height / 2 - centerY
    - relativeScale * (target.top + target.height / 2 - centerY - current.m42);
  return `translate3d(${x}px, ${y}px, 0) scale(${relativeScale * Math.hypot(current.m11, current.m12)})`;
}

function inferredMediaFile(file: File): File {
  if (file.type && file.type !== 'application/octet-stream') return file;
  const video = videoMimeType({ mimeType: file.type, originalName: file.name });
  const extension = file.name.match(/\.(jpe?g|png|gif|webp|heic|heif|avif)$/i)?.[1]?.toLowerCase();
  const image = extension === 'jpg' || extension === 'jpeg' ? 'image/jpeg'
    : extension === 'png' ? 'image/png'
    : extension === 'gif' ? 'image/gif'
    : extension === 'webp' ? 'image/webp'
    : extension === 'heic' || extension === 'heif' ? 'image/heic'
    : extension === 'avif' ? 'image/avif'
    : '';
  const type = video ?? image;
  return type ? new File([file], file.name, { type, lastModified: file.lastModified }) : file;
}

function isDesktopBrowser(): boolean {
  const agent = navigator as Navigator & { userAgentData?: { mobile?: boolean }; standalone?: boolean };
  // Screen size and an attached keyboard do not identify a desktop browser.
  // iPad desktop mode also reports Macintosh, but retains touch capabilities.
  if (agent.userAgentData?.mobile || /Android|iPhone|iPad|iPod|Mobile|Tablet/i.test(agent.userAgent)) return false;
  if (/Macintosh/i.test(agent.userAgent) && agent.maxTouchPoints > 1) return false;
  return /Windows NT|Macintosh|X11|CrOS/i.test(agent.userAgent);
}

type DesktopReturn = {
  vault?: Pick<VaultSession, 'key' | 'stored' | 'browserAccessPrf'>;
  credential?: PlatformCredentialResult | null;
  browser?: { proof: Uint8Array<ArrayBuffer>; record: PlatformCredentialRecord };
  settled: Promise<unknown>;
};

